key.harness:
`timescale 1ns/1ps
// The grading testbench. The sample one has a single clean match in
// it; this one has the overlapping cases, a long run of ones, a reset
// in the middle of a partial match, and a check on exactly which
// cycle found is high.
module tb;
  logic clk = 1'b0, rst = 1'b1, din = 1'b0, found;
  int hits = 0;
  int pulse_cycle = -1;
  int cycle = 0;

  seq1101 dut (.clk(clk), .rst(rst), .din(din), .found(found));

  always #5 clk = ~clk;
  always @(negedge clk) begin
    cycle++;
    if (found) begin
      hits++;
      if (pulse_cycle < 0) pulse_cycle = cycle;
    end
  end

  task automatic feed(input logic [31:0] bits, input int n);
    for (int i = n - 1; i >= 0; i--) begin
      @(negedge clk) din = bits[i];
      @(posedge clk);
    end
  endtask

  initial begin
    @(posedge clk); @(negedge clk);
    $display("CHECK after_reset 0 %b AT %0d", found, $time);
    rst = 1'b0;

    // 1101 once. Record which cycle the pulse landed in.
    @(negedge clk) #1 begin cycle = 0; pulse_cycle = -1; end
    feed(32'b1101, 4);
    @(negedge clk); #1;
    $display("CHECK one_match 1 %0d AT %0d", hits, $time);
    // Four bits are fed in cycles 1..4, so the pulse belongs to cycle 5.
    $display("CHECK timing 5 %0d AT %0d", pulse_cycle, $time);

    din = 1'b0; repeat (3) @(posedge clk);

    // 1101101 — two matches, overlapping on the shared 1.
    @(negedge clk) #1 hits = 0;
    feed(32'b1101101, 7);
    repeat (2) @(posedge clk); @(negedge clk); #1;
    $display("CHECK overlapping 2 %0d AT %0d", hits, $time);

    din = 1'b0; repeat (3) @(posedge clk);

    // A long run of ones completes nothing: the machine must sit in
    // "seen 11" rather than cycling back to the start.
    @(negedge clk) #1 hits = 0;
    feed(32'b11111111, 8);
    repeat (2) @(posedge clk); @(negedge clk); #1;
    $display("CHECK long_run_of_ones 0 %0d AT %0d", hits, $time);

    // 1101101101 — three overlapping matches.
    @(negedge clk) #1 hits = 0;
    din = 1'b0; repeat (3) @(posedge clk);
    feed(32'b1101101101, 10);
    repeat (2) @(posedge clk); @(negedge clk); #1;
    $display("CHECK three_overlaps 3 %0d AT %0d", hits, $time);

    // Reset part way through 110, then finish the pattern. The 1 that
    // follows cannot complete anything, because the 110 before it was
    // thrown away.
    @(negedge clk) #1 hits = 0;
    din = 1'b0; repeat (2) @(posedge clk);
    feed(32'b110, 3);
    @(negedge clk) rst = 1'b1;
    @(posedge clk);
    @(negedge clk) rst = 1'b0;
    feed(32'b1, 1);
    repeat (3) @(posedge clk); @(negedge clk); #1;
    $display("CHECK reset_mid_pattern 0 %0d AT %0d", hits, $time);

    $display("DONE 7");
    $finish;
  end
endmodule

reference.sv:
module seq1101 (
  input  logic clk,
  input  logic rst,
  input  logic din,
  output logic found
);

  typedef enum logic [1:0] { S0, S1, S11, S110 } state_t;
  state_t state, next;

  // How much of 1101 has been seen. The state name is the prefix.
  always_comb begin
    unique case (state)
      S0:   if (din) next = S1;   else next = S0;
      S1:   if (din) next = S11;  else next = S0;
      S11:  if (din) next = S11;  else next = S110;
      S110: if (din) next = S1;   else next = S0;
      default: next = S0;
    endcase
  end

  always_ff @(posedge clk) begin
    if (rst) begin
      state <= S0;
      found <= 1'b0;
    end else begin
      state <= next;
      // The match completes when a 1 arrives in S110. Registered, so
      // it is reported in the following cycle.
      found <= (state == S110) && din;
    end
  end

endmodule
